import { createHash } from "node:crypto";
import { describe, expect, test } from "bun:test";
import { parseCsdl } from "../src/schema/csdl.ts";

// Metadata generated by aster-webdata-server, not written by this repository.
const dir = new URL("../../../fixtures/metadata-reference/", import.meta.url);
const text = await Bun.file(new URL("metadata.json", dir)).text();
const manifest = await Bun.file(new URL("manifest.json", dir)).json();
const json = JSON.parse(text);

describe("parseCsdl: server reference metadata", () => {
  test("the file is the one the manifest describes", () => {
    expect(createHash("sha256").update(text).digest("hex")).toBe(manifest.sha256["metadata.json"]);
  });

  test("every entity set loads and nothing is skipped", () => {
    const s = parseCsdl(json);
    expect([...s.sets.keys()].sort()).toEqual([...manifest.entity_sets].sort());
    expect(s.skipped).toEqual([]);
  });

  test("the document carries the operations the client ignores", () => {
    const ns = json[parseCsdl(json).namespace];
    for (const name of Object.keys(manifest.operation_overloads)) {
      expect(Array.isArray(ns[name])).toBe(true);
    }
  });

  test("a property of a type definition takes its underlying type and annotations", () => {
    const s = parseCsdl(json);
    for (const set of ["Items", "SpecialItems"]) {
      const f = s.set(set).type.field("reference")!;
      expect(f.type).toBe("Edm.String");
      expect(f.nullable).toBe(true);
      expect(f.annotations["AsterData.Encoding"]).toBe("decimal");
      expect(f.annotations["AsterData.StoredType"]).toBe("Int64");
    }
  });
});
